public class Main {
    public static int sumCsv(String s) {
        String[] parts = s.split(",");
        int sum = 0;
        for (String p : parts) {
            String t = p.trim();
            if (!t.isEmpty()) sum += Integer.parseInt(t);
        }
        return sum;
    }
    public static void main(String[] args) {
        System.out.println(sumCsv("1,2,3"));
    }
}

