solutionCode:
#include <stdio.h>
#include <stdlib.h>

int sumCsv(const char* s) {
    int sum = 0;
    const char* p = s;
    char buf[32];
    int bi = 0;
    while (1) {
        char c = *p;
        if (c == ',' || c == '\0') {
            buf[bi] = '\0';
            if (bi > 0) sum += atoi(buf);
            bi = 0;
            if (c == '\0') break;
        } else if (c != ' ') {
            if (bi < 31) buf[bi++] = c;
        }
        p++;
    }
    return sum;
}

int main() {
    printf("%d\n", sumCsv("1,2,3"));
    return 0;
}

