solutionCode:
#include <stdio.h>
#include <stdbool.h>

bool isPalindrome(const char* s) {
    int n = 0;
    while (s[n] != '\0') n++;
    int i = 0, j = n - 1;
    while (i < j) {
        if (s[i] != s[j]) return false;
        i++; j--;
    }
    return true;
}

int main() {
    printf("%d\n", isPalindrome("level"));
    return 0;
}
